import sys

def main():
    data = list(map(int, sys.stdin.read().split()))
    if not data:
        return

    n = data[0]
    a = data[1:1 + n]

    INF = 10**9

    left = [INF] * n
    d = INF
    for i in range(n):
        if a[i] == 0:
            d = 0
        else:
            d += 1
        left[i] = d

    right = [INF] * n
    d = INF
    for i in range(n - 1, -1, -1):
        if a[i] == 0:
            d = 0
        else:
            d += 1
        right[i] = d

    ans = []
    for i in range(n):
        dist = min(left[i], right[i])
        if dist >= 9:
            dist = 9
        ans.append(str(dist))

    sys.stdout.write(" ".join(ans) + "\n")

if __name__ == "__main__":
    main()
